\label{thm:upper_asymptotics}
     Suppose either the condition \eqref{cond_A} or the condition \eqref{cond_B} hold. Then,
    \begin{itemize}
        \item let $T$ be a measurable selector constructed in Lemma~\ref{lemma:pi_s_k_single_valued}, for $r\geq 1$, \begin{align*}
            &\underline{\widehat{\dim}}_Q^{r}{(P;S)}\leq\underline{\dim}_B^{*}{(T_*P)}\leq\underline{\dim}_B^{}{(\pi_S(K))},\,\,\overline{\widehat{\dim}}_Q^{r}{(P;S)}\leq\overline{\dim}_B^{*}{(T_*P)}\leq\overline{\dim}_B^{}{(\pi_S(K))};\\
             &\underline{\widetilde{\dim}}_Q^{r}{(P;S)}\leq\underline{\dim}_B^{*}{(T_*P)}\leq\underline{\dim}_B^{}{(\pi_S(K))},\,\,\overline{\widetilde{\dim}}_Q^{r}{(P;S)}\leq\overline{\dim}_B^{*}{(T_*P)}\leq\overline{\dim}_B^{}{(\pi_S(K))};
        \end{align*}
        \item for $r>0$, if $\pi_S(K)$ is Ahlfors regular of dimension $d$, then, 
        \begin{align*}
            \dim_H(\pi_S(K))&\geq \overline{\widetilde{\dim}}_Q^{r}{(P;S)}\geq \underline{\widetilde{\dim}}_Q^{r}{(P;S)},\\\dim_H(\pi_S(K))&\geq \overline{\widetilde{\dim}}_Q^{\infty}{(P;S)}\geq \underline{\widetilde{\dim}}_Q^{\infty}{(P;S)},\\ \dim_H(\pi_S(K))&\geq\overline{\widehat{\dim}}_Q^{1}{(P;S)}\geq\underline{\widehat{\dim}}_Q^{1}{(P;S)}.
        \end{align*}
    \end{itemize}

\label{thm:lower_asymptotics}
 Suppose the condition \eqref{cond_L1} is true. Let $r\geq 1$. In addition, suppose the pushforward measure as constructed in Lemma~\ref{lemma:pi_s_k_single_valued} is upper Ahlfors regular of dimension $d$. Then,
    \begin{itemize}
        \item $\underline{\widehat{\dim}}_Q^{r}{(P;S)}\geq \dim_H^*({T_*P})$ and $\underline{\widetilde{\dim}}_Q^{r}{(P;S)}\ge \dim_H^*({T_*P})$;
        \item if the condition \eqref{cond_D} is true, then $\dim_H(T(K))=\dim_H^*({T_*P})$, $\dim_H(T(K))\le \underline{\widehat{\dim}}_Q^{r}{(P;S)}$ and $\dim_H(T(K))\le \underline{\widehat{\dim}}_Q^{r}{(P;S)}$
    \end{itemize}

\label{prop:dimensions_in_articles}
    \begin{itemize}
        \item In \cite{graf}, if $P$ is a compactly supported probability on $K$ and $1\leq r\leq s\leq\infty$, then \(\underline{\dim}_B^{}{(K)}=\underline{\dim}_Q^{\infty}{(P)}=\underline{\dim}_Q^{\infty}{(K)}\geq \underline{\dim}_Q^{s}{(P)}\geq\underline{\dim}_Q^{r}{(P)}\) and \(\overline{\dim}_B^{}{(K)}=\overline{\dim}_Q^{\infty}{(P)}=\overline{\dim}_Q^{\infty}{(K)}\geq \overline{\dim}_Q^{s}{(P)}\geq\overline{\dim}_Q^{r}{(P)}\);
        \item In \cite{graf}, let $P$ be a probability, for $r\geq 1$, $\dim_H^*({P})\leq \underline{\dim}_Q^{r}{(P)}$;
        \item In \cite{dai2008quantization}, if $P$ is a probability on $\bigtimes\limits_{i=1}^D [0,1]$ and $0<r<\infty$, then $\dim_P^*({P})\leq \overline{\dim}_Q^{^r}{(P)}$ and $\dim_H^*({P})\leq \underline{\dim}_Q^{r}{(P)}$;
        \item In \cite{kloeckner2012}, if $P$ Ahlfors regular of dimension $d$ and compactly supported on a stable Riemannian manifold, let $\infty>r\geq 1$, then $0<\liminf\limits_{n\rightarrow\infty}ne_{n,r}^{d}(P)\leq \limsup\limits_{n\rightarrow\infty}ne_{n,r}^{d}(P)<\infty$, that is, $\underline{\dim}_Q^{r}{(P)}=\overline{\dim}_Q^{r}{(P)}=d$
    \end{itemize}

\label{lemma:existence_previously}
    Let $1\leq r<\infty$. Suppose $P$ is a Borel probability on $\mathbb R^D$, and $S\subseteq \mathbb R^D$ is a closed set. Then
    \begin{itemize}
        \item $C_{1,r}(P;S)$ is nonempty;
        \item If there exists at least $n$ elements in $S$ whose Voronoi regions have positive probability, then $C_{n,r}(P;S)$ is nonempty and $|\alpha|=n$ for any $\alpha\in C_{n,r}(P;S)$;
        \item $C_{n,\infty}(P;S)$ is nonempty if $\text{\normalfont supp} {(P)}\Subset \mathbb R^D$ is compact.
    \end{itemize}

\label{lemma:monotone_e_n_infty_e_n_r_constrained_10.1}
    Let $n\in\mathbb N$, $S\subseteq\text{\normalfont supp} {(P)} \subseteq\mathbb R^D$. Suppose $1\leq r\leq s\leq\infty$, then \[e_{n,r}(P;S)\leq e_{n,s}(P;S)\]
    Furthermore, if $S\Subset \mathbb R^D$ then \[\lim\limits_{r\rightarrow \infty}e_{n,r}(P;S)=e_{n,\infty}(P;S)\]

Suppose $K\Subset \mathbb R^D$ is compact, then $C_{n,\infty}(K)$ is nonempty, plus $$e_{n,\infty}(K)=\inf\limits_{\substack{\alpha\subseteq \mathbb R^D\\ |\alpha|\leq n}}d_H(\alpha,K)$$
    In addition, suppose $S\subseteq \mathbb R^D$ is closed (and therefore $\pi_S(K)$ is compact) then $C_{n,\infty}(K;S)$ is nonempty with $$e_{n,\infty}(K;S)=\inf\limits_{\substack{\alpha\subseteq S\\ |\alpha|\leq n}}d_H(\alpha,K)$$
    \label{lemma:e_n_infty_and_hausdorff_10.4}

First, we claim that for $\overline{x}\in K$, there exists $G(\overline{x})$ a closed set containing $\overline{x}$, and there exists a continuous function $f:G(\overline{x})\rightarrow S$ such that $f(x)\in \pi_S(x)$ for $x\in G(\overline{x})$. To prove the first claim, it suffices to show that $f$ is continuous on $\overline{x}$, which is guaranteed by the Lemma~\ref{lemma:approximation_pi_s_x_and_pi_s_x_n}, by the compactness of $G(\overline{x})$. For each $\overline{x}$, we can generate such a continuous function at $\overline{x}$ which is also continuous on a closed neighborhood $G(\overline{x})$. Therefore, $\bigcup\limits_{\overline{x}\in K}G(\overline{x})$ forms a cover of $K$ and there exists a finite subcover $\bigcup\limits_{i=1}^k G(x_i)$, with corresponding continuous function $f_i$ on $x_i$ and $G(x_i)$. By the axiom of choice, there exists a map $T:K\rightarrow S$ with $T(x)\in \pi_S(x)$ such that $T(x)=f_i(x)$ for some $1\leq i\leq k$. We would like to show that $T^{-1}(U)$ is measurable where $U$ is open in the sense of subspace topology on $S$. Let $M_i$ be a integer only dependent to $i$, then we have
    \begin{align*}
        T^{-1}(U)=\bigcup\limits_{i=1}^k \bigg({G(x_i)\cap T^{-1}(U)}\bigg)=\bigcup\limits_{i=1}^k\bigcup\limits_{l=1}^{M_i}f_i^{-1}(E_l)
    \end{align*}
    where $\{E_l\}_{l\leq M_i}$ are Borel sets and are generated by finite set operations by how we define $T$ by $f_i$ previously. We can argue from above that $T^{-1}(U)$ is Borel, and therefore measurable.

Let $t=\dim_H(T(K))$. First, we claim that if $0.9355(T(x),T(y))\leq C'0.9355(x,y)$, then $\dim_H(T(K))\leq\dim_H(K)$. To show the claim, consider $K\subset igcup\limits_{i=1}^\infty U_i$ where $	ext{
