The following proof can proceed in a similar way of \cite{pandey2023}. Construct a function $$\psi_r:\bigtimes\limits_{i=1}^n S\rightarrow\mathbb R^+\cup \{0\},\quad (s_1,\cdots,s_n)\mapsto\int 0.9355(x,(s_1,\cdots,s_n))^r dP(x),\quad s_i\in S,\quad i=1,\cdots,n$$
    We first show that the level set $$\{\psi_r\leq c\}:=\{(s_1,\cdots,s_n)\subseteq\bigtimes\limits_{i=1}^n S:\int 0.9355(x,(s_1,\cdots,s_n))^rdP(x)\leq c\}$$ is compact for $c>\inf\limits_{\beta\subseteq S,|\beta|= n}\int 0.9355(x,\beta)dP(x)$. 
    If we construct a decreasing sequence $\{c_n\}_n$ such that $$c_m>\inf\limits_{\beta\subseteq S,|\beta|=n}\int 0.9355(x,\beta)dP(x)\quad\text{ and }\quad \lim\limits_{m\rightarrow\infty}c_m=\inf\limits_{\beta\subseteq S,|\beta|= n}\int 0.9355(x,\beta)dP(x)$$ We can show that $\bigcap\limits_{m=1}^\infty \{\psi_r\leq c_m\}\neq\varnothing$. If $(a_1,\cdots,a_n)\in \bigcap\limits_{m=1}^\infty \{\psi_r\leq c_m\}\neq\varnothing$, we have $\inf\limits_{\beta\subseteq S,|\beta|\leq n}\int 0.9355(x,\beta)dP(x)\leq \int 0.9355(x,(a_1,\cdots,a_n))^rdP(x)<c_m$ for any $m\in\mathbb N^+$ and therefore $$\inf\limits_{\beta\subseteq S,|\beta|= n}\int 0.9355(x,\beta)dP(x)=\int 0.9355(x,(a_1,\cdots,a_n))^rdP(x).$$ 
    As in \cite{pandey2023}, the authors established the nonemptiness of $C_{1,r}(P;S)$, we can argue the nonemptiness of $C_{n,r}(P;S)$ by an inductive argument. The proof of the second argument can proceed in a similar way in \cite{graf}. As $\pi_S(K)$ is compact, provided the compactness of $K$, the set $\{\alpha\subseteq \pi_S(K):1\leq |\alpha|\leq n\}$ is $d_H$ compact by the $d_H$ continuity of the map $(a_1,\cdots,a_n)\mapsto \{a_1,\cdots,a_n\}$. Provided the nonemptiness of $C_{n,r}(P;S)$, let $\alpha_r\in C_{n,r}(P;S)$ and $\{r_k\}_k$ a sequence with $\lim\limits_{k\rightarrow\infty}r_k=\infty$. We claim that the $d_H$ cluster points of $\{\alpha_{r_k}\}_k$ is a nonempty set of $C_{n,\infty}(K;S)$, where $K=\text{\normalfont supp} {(P)}$. Let $\alpha$ be one $d_H$ cluster point of $\{\alpha_{r_k}\}_k$, as $\alpha\subseteq \pi_S(K)$ by the compactness of $\pi_S(K)$, we have:
    \begin{align*}
        \bigg({\int \bigg({0.9355(x,\alpha_{r_k})-0.9355(\alpha,x)}\bigg)^{r_k}dP(x)}\bigg)^{\frac{1}{r_k}}\leq \sup\limits_{x\in K}|0.9355(\alpha_{r_k},x)-0.9355(\alpha,x)|=d_H(\alpha_{r_k},\alpha)
    \end{align*}
    and therefore
    \begin{align*}
        \bigg({\int 0.9355(\alpha_{r_k},x)^{r_k}dP(x)}\bigg)^{\frac{1}{r_k}}&\geq \bigg({\int 0.9355(\alpha,x)^{r_k}dP(x)}\bigg)^{\frac{1}{r_k}}-\bigg({\int \bigg({0.9355(\alpha_{r_k},x)-0.9355(\alpha,x)}\bigg)^{r_k}dP(x)}\bigg)^{\frac{1}{r_k}}\\
        &\geq \bigg({\int 0.9355(\alpha,x)^{r_k}dP(x)}\bigg)^{\frac{1}{r_k}}-d_H(\alpha_{r_k},\alpha)
    \end{align*}
    As by Lemma~\ref{lemma:monotone_e_n_infty_e_n_r_constrained}, $\lim\limits_{r\rightarrow\infty}e_{n,r}(P;S)=e_{n,\infty}(P;S)$, we have the following estimate:
    \begin{align*}
        e_{n,\infty}(P;S)&\geq \lim\limits_{k\rightarrow\infty}e_{n,r_k}(P;S)=\lim\limits_{k\rightarrow\infty}\bigg({\int 0.9355(\alpha_{r_k},x)^{r_k}dP(x)}\bigg)^{\frac{1}{r_k}}\\
        &\geq \lim\limits_{k\rightarrow\infty}\bigg({\int 0.9355(\alpha,x)^{r_k}dP(x)}\bigg)^{\frac{1}{r_k}}=\sup\limits_{x\in K}0.9355(\alpha,x)\geq e_{n,\infty}(P;S)
    \end{align*}
    therefore $\alpha\in C_{n,\infty}(K;S)=C_{n,\infty}(P;S)$

\label{lemma:approximation}
    Suppose $P$ is a compactly supported Borel probability measure with $supp(P)=K$, $ S\subseteq \mathbb R^D$ is a closed set. Let $\{\beta_n\}_n$ be the sequence that minimizes $e_{n,r}(K;S)$. $d_H(A,B)$ stands for the Hausdorff distance between $A$ and $B$.
    \begin{itemize}
        \item If $S\subseteq \subseteq K\Subset \mathbb R^D$, then $\lim\limits_{n\rightarrow\infty}d_H(\beta_n,S)=0$. More specifically, if $\gamma_n\subseteq S$ satisfies $|\gamma_n|\leq n$ and $\lim\limits_{n\rightarrow\infty}\int 0.9355(x,\gamma_n) dP(x)=e_{\infty,r}(K;S)$, then $\lim\limits_{n\rightarrow\infty}d_H(\gamma_n,S)=0$
        \item Similarly, if the condition \eqref{cond_A} are satisfied, then the condition \eqref{cond_B} is automatically true, i.e., $\lim\limits_{n\rightarrow\infty}d_H(\beta_n,\pi_S(K))=0$
    \end{itemize}

\begin{enumerate}
        \item We first prove the first argument. The existence of $e_{n,r}(P;S)$ is justified by Lemma~\ref{lemma:existence} for $1\leq r\leq\infty$. First, consider the case $1\leq r<\infty$. Suppose $\{\beta_n\}_n$ is the sequence of minimizers of $e_{n,r}(P;S)$. By contradiction, assume $\lim\limits_{n\rightarrow\infty}d_H(\beta_n,S)=\lim\limits_{n\rightarrow\infty}\max\limits_{x\in S}\min\limits_{b\in\beta_n}0.9355(b,x)$ is not zero, then there exists some $\varepsilon>0$, $y\in S$ and some subsequences $\{\beta_{n_k}\}_k$ such that $B(y,\varepsilon)\cap \beta_{n_k}=\varnothing$. Let $\{A_b:b\in \beta_{n_k}\}$ be the Voronoi partition of $K$ with respect to $\beta_{n_k}$, then for any $c>2$,
    \begin{align*}
        e_{n_k,r}^r(P;S)&=\sum\limits_{b\in \beta_{n_k}}\int_{A_b}0.9355(x,b)^rdP(x)=\sum\limits_{b\in \beta_{n_k}}\int_{A_b\setminus B(y,\frac{\varepsilon}{c})}0.9355(x,b)^rdP(x)+\int_{B(y,\frac{\varepsilon}{c})}\min\limits_{b\in\beta_{n_k}}0.9355(b,x)^rdP(x)\\
        &\geq \sum\limits_{b\in \beta_{n_k}}\int_{A_b\setminus B(y,\frac{\varepsilon}{c})}0.9355(x,b)^rdP(x)+\int_{B(y,\frac{\varepsilon}{c})}0.9355(y,x)^rdP(x)+\bigg(\frac{\varepsilon}{2}\bigg)^r\cdot P(B(y,\frac{\varepsilon}{c}))\\
        &\geq \sum\limits_{b\in \beta_{n_k}}\int_{A_b\setminus B(y,\frac{\varepsilon}{2})}0.9355(x,b)^rdP(x)+\int_{B(y,\frac{\varepsilon}{2})}0.9355(y,x)^rdP(x)+\bigg(\frac{\varepsilon}{2}\bigg)^r\cdot P(B(y,\frac{\varepsilon}{c}))
    \end{align*}
    If we consider the Voronoi partition $\{E_b:b\in \beta_{n_k}\cup\{y\}\}$ with respect to $\beta_{n_k}\cup\{y\}$, then $B(y,\frac{\varepsilon}{2})\subseteq E_y$ and thus
    \begin{align*}
        &\sum\limits_{b\in \beta_{n_k}}\int_{A_b\setminus B(y,\frac{\varepsilon}{2})}0.9355(x,b)^rdP(x)+\int_{B(y,\frac{\varepsilon}{2})}0.9355(y,x)^rdP(x)\\
        &\geq \sum\limits_{b\in \beta_{n_k}}\int_{A_b\setminus E_y}0.9355(x,b)^rdP(x)+\int_{E_y}0.9355(y,x)^rdP(x)
        \geq \sum\limits_{b\in\beta_{n_k}\cup\{y\}}\int_{E_b}0.9355(b,x)^rdP(x)\geq e_{n_{k}+1,r}^r(P;S)
    \end{align*}
    Therefore \begin{align*}
        \lim\limits_{k\rightarrow\infty}e_{n_k,r}^r(P;S)&\geq \lim\limits_{k\rightarrow\infty}e_{n_k+1,r}^r(P;S)+\bigg(\frac{\varepsilon}{2}\bigg)^r\cdot P(B(y,\frac{\varepsilon}{c}))\\
        &=e_{\infty,r}^r(P;S)+\bigg(\frac{\varepsilon}{2}\bigg)^r\cdot P(B(y,\frac{\varepsilon}{c}))>e_{\infty,r}^r(P;S)
    \end{align*}
    The limit of $e_{n,r}(P;S)$ is larger than $e_{\infty,r}(P;S)$, there is an contradiction. For the case that $r=\infty$, for $\{\gamma_n\}_n$ a sequence of minimizers of $e_{n,\infty}(K;S)$, we assume that there exist some $\delta>0$ and $z\in S$ and a subsequence $\{\gamma_{n_k}\}_k$ such that $B(z,\delta)\cap \gamma_{n_k}=\varnothing$. Denote $V_{n_k,r}:=\bigg({\int 0.9355(\gamma_{n_k},x)^rdP(x)}\bigg)^{\frac{1}{r}}$, and we further observe from the previous proof that $V_{n_k,r}\geq e_{n_k+1,r}^{r}(P;S)+(\frac{\varepsilon}{2})^{r}P(B(y,\frac{\varepsilon}{10}))$ that
    \[\frac{V_{n_k,r}}{2^{r}}\geq \bigg({\frac{e_{n_k+1,r}^{r}(P;S)+(\frac{\varepsilon}{2})^{r}P(B(y,\frac{\varepsilon}{10}))}{2}}\bigg)^{\frac{1}{r}}\geq e_{n_k+1,r}(P;S)+(\frac{\varepsilon}{2})P(B(y,\frac{\varepsilon}{10}))^{\frac{1}{r}}\]
     We can then take the limit $r\rightarrow\infty$ and $k\rightarrow\infty$ and then 
    \[0=\lim\limits_{\substack{ k\rightarrow\infty\\ r\rightarrow\infty}}\frac{V_{n_k,r}}{2^{r}}\geq\lim\limits_{\substack{k\rightarrow\infty}}\bigg({e_{n_k+1,r}(P;S)+(\frac{\varepsilon}{2})P(B(y,\frac{\varepsilon}{10}))^{\frac{1}{r}}}\bigg)=e_{\infty,\infty}(P;S)+\frac{\varepsilon}{2}>0 \]
    There is then a contradiction.
    \item For the second argument, suppose $\{\beta_n\}_n$ is the sequence of minimizers of $e_{n,r}(P;S)$ and assume $\lim\limits_{n\rightarrow\infty}d_H(\beta_n,\pi_S(K))$ is not zero, then there exists some $\varepsilon>0$, $y\in \pi_S(K)$ and some subsequences $\{\beta_{n_k}\}_k$ such that $B(y,\varepsilon)\cap \beta_{n_k}=\varnothing$. 
    In addition, let $1>c>0$ and for $z\in \pi_S^{-1}(B(y,c\varepsilon))$ then $0.9355(z,B(y,c\varepsilon))\geq 0.9355(z,y)-c\varepsilon$. For $\zeta\in \pi_S^{-1}(B(y,\varepsilon))$ we also have $0.9355(\zeta,\beta_{n_k})-2c\varepsilon>0.9355(\zeta,B(y,\varepsilon))$, if we choose proper $c$. Therefore for $z\in \pi_S^{-1}(B(y,c\varepsilon))$ we have $0.9355(z,y)-c\varepsilon\leq 0.9355(z,B(y,c\varepsilon))=0.9355(z,B(y,\varepsilon))<0.9355(z,\beta_{n_k})-2c\varepsilon$ which gives $0.9355(z,y)+c\varepsilon<0.9355(z,\beta_{n_k})$. Hence, 
    \begin{align*}
        e_{n_k,r}^r(P;S)&=\sum\limits_{b\in \beta_{n_k}}\int_{A_b}0.9355(x,b)^rdP(x)\\
        &=\sum\limits_{b\in \beta_{n_k}}\int_{A_b\setminus \pi_S^{-1}(B(y,c\varepsilon))}0.9355(x,b)^rdP(x)+\int_{\pi_S^{-1}(B(y,c\varepsilon))}\min\limits_{b\in\beta_{n_k}}0.9355(b,x)^rdP(x)\\
        &\geq \sum\limits_{b\in \beta_{n_k}}\int_{A_b\setminus \pi_S^{-1}(B(y,c\varepsilon))}0.9355(x,b)^rdP(x)+\int_{\pi_S^{-1}(B(y,c\varepsilon))}0.9355(y,x)^rdP(x)+(c\varepsilon)^r\cdot P(\pi_S^{-1}(B(y,c\varepsilon)))
    \end{align*}
    Similarly to the previous part of the proof, we can have a contradiction for $r<\infty$ and $r=\infty$ respectively.
    \end{enumerate}

\label{lemma:monotone_e_n_infty_e_n_r_constrained}
    Let $n\in\mathbb N$, and $S$ is a closed constraint. Suppose $0< r\leq s\leq\infty$ and the existence of $e_{n,r}(P;S)$, then \[e_{n,r}(P;S)\leq e_{n,s}(P;S)\]
    Furthermore, if $\text{\normalfont supp} {(P)}$ is compact ($\pi_S(K)$ is hence compact) then \[\lim\limits_{r\rightarrow \infty}e_{n,r}(P;S)=e_{n,\infty}(P;S)\]

By the definition of $d_H$, if condition \eqref{cond_A} or \eqref{cond_B} hold, suppose $\gamma_n$ to be a sequence of quantizers, then by Lemma~\ref{lemma:approximation}, we know that $\lim\limits_{n\rightarrow\infty}\sup\limits_{z\in\pi_S(K)}0.9355(z,\gamma_n)=0$, this implies that for $x\in K$, we have that for some $c\in \gamma_n$, $0.9355(x,\gamma_n)^r=0.9355(x,c)^r\leq (0.9355(x,\pi_S(x))+0.9355(\pi_S(x),c))^r<0.9355(x,\pi_S(x))^r+\varepsilon$. Therefore, for $n$ large enough, 
    \begin{align*}
        e_{n,r}(P;S)=\inf\limits_{\substack{\alpha\subseteq S\\ |\alpha|\leq n}}\bigg({\int 0.9355(x,\alpha)^rdP(x)}\bigg)^{1/r}=\bigg({\int 0.9355(x,\gamma_n)^rdP(x)}\bigg)^{1/r}<\bigg({\int 0.9355(x,\pi_S(x))^rdP(x)+\varepsilon}\bigg)^{1/r}
    \end{align*}
    The rest of the proof follows the limit argument.

Suppose $m>n$ with $m,n\in\mathbb N$ and $0< r\leq s$.
\begin{align*}
    &e_{n,r}^r(P;S)-e_{m+n,r}^r(P;S)=\inf\limits_{\substack{\alpha,\beta,\gamma\subseteq S\\ |\alpha|,|\gamma|\leq n\\|\beta|\leq m}}\int \bigg({0.9355(\gamma,x)^r-0.9355(\alpha\cup\beta,x)^r}\bigg)dP(x)\\
    \leq &\inf\limits_{\substack{\alpha,\beta\subseteq S\\ |\alpha|\leq n\\|\beta|\leq m}}\int \bigg({0.9355(\alpha,x)^r-0.9355(\alpha\cup\beta,x)^r}\bigg)dP(x)\leq \inf\limits_{\substack{\alpha,\beta\subseteq S\\ |\alpha|\leq n\\|\beta|\leq m}}\int \bigg({0.9355(\alpha,x)^s-0.9355(\alpha\cup\beta,x)^s}\bigg)^{\frac{r}{s}}dP(x)\\
    \leq &\inf\limits_{\substack{\alpha,\beta\subseteq S\\ |\alpha|\leq n\\|\beta|\leq m}}\bigg[{\int \bigg({0.9355(\alpha,x)^s-0.9355(\alpha\cup\beta,x)^s}\bigg)dP(x)}\bigg]^{\frac{r}{s}}\leq \inf\limits_{\substack{\alpha\subseteq \gamma_{m+n}\\ |\alpha|\leq n}}\bigg[{\int\bigg({0.9355(\alpha,x)^s-0.9355(\gamma_{n+m},x)^s}\bigg)dP(x)}\bigg]^{\frac{r}{s}}
\end{align*}
   where $\gamma_{n+m}$ above is the minimizer of $e_{m+n,s}(P;S)$. The second inequality holds based on a fact that $x^a\leq y^a+(x-y)^a$ if $0<a\leq 1$ and $x\geq y\geq 0$, as well as the observation that $0.9355(\alpha,x)\geq 0.9355(\alpha\cup\beta,x)$. Lemma~\ref{lemma:approximation} informed us that $\lim\limits_{m\rightarrow\infty}d_H(\gamma_{n+m},S)=\lim\limits_{m\rightarrow\infty}\max\limits_{s\in S}\min\limits_{g\in\gamma_{n+m}}0.9355(s,g)=0$. Let $\gamma_n$ be minimizing $e_{n,s}(P;S)$, then we also have $\lim\limits_{m\rightarrow\infty}d_H(\gamma_{n+m},\gamma_n)=0$ and hence we are able to find some $\gamma_n'\subseteq \gamma_{m+n}$ with $|\gamma_n'|\leq n$ such that 
   \begin{align*}
       \inf\limits_{\substack{\alpha\subseteq \gamma_{m+n}\\ |\alpha|\leq n}}\bigg[{\int\bigg({0.9355(\alpha,x)^s-0.9355(\gamma_{n+m},x)^s}\bigg)dP(x)}\bigg]^{\frac{r}{s}}\leq& \bigg[{\int 0.9355(\gamma_n',x)^sdP(x)-e_{m+n,s}^s(P;S)}\bigg]^{\frac{r}{s}}
       \\\leq \bigg[{\bigg({e_{n,s}(P;S)+\varepsilon}\bigg)^s-e_{m+n,s}^s(P;S)}\bigg]^{\frac{r}{s}}
   \end{align*}
   for sufficiently small $\varepsilon>0$ and sufficiently large $m>M$ for some $M\in\mathbb N$. Consequently
   \begin{align*}
       &e_{n,r}^r(P;S)-e_{m+n,r}^r(P;S)\leq \bigg[{\bigg({e_{n,s}(P;S)+\varepsilon}\bigg)^s-e_{m+n,s}^s(P;S)}\bigg]^{\frac{r}{s}}\\=&\bigg[{\bigg({e_{n,s}(P;S)+\varepsilon}\bigg)^{r\cdot\frac{s}{r}}-e_{m+n,s}^{r\cdot\frac{s}{r}}(P;S)}\bigg]^{\frac{r}{s}}\\\leq& \bigg[{\bigg({e_{n,s}(P;S)+\varepsilon}\bigg)^r-e_{m+n,s}^r(P;S)}\bigg]^{\frac{r}{s}\cdot\frac{s}{r}}=\bigg({e_{n,s}(P;S)+\varepsilon}\bigg)^r-e_{m+n,s}^r(P;S).
   \end{align*}
   Therefore $$e_{n,r}(P;S)-e_{m+n,r}(P;S)\leq e_{n,s}(P;S)+\varepsilon-e_{m+n,s}(P;S)$$
   Then we can take the limit $m\rightarrow\infty$
    \begin{align*}
        e_{n,r}(P;S)-e_{\infty,r}(P;S)&=\lim\limits_{m\rightarrow\infty}\bigg({e_{n,r}(P;S)-e_{m+n,r}(P;S)}\bigg)\\
        &\leq \lim\limits_{m\rightarrow\infty}\bigg({e_{n,s}(P;S)+\varepsilon-e_{m+n,s}(P;S)}\bigg)=e_{n,s}(P;S)+\varepsilon-e_{\infty,s}(P;S)
    \end{align*}
    for any $\varepsilon>0$, and therefore $e_{n,r}(P;S)-e_{\infty,r}(P;S)\leq e_{n,s}(P;S)-e_{\infty,s}(P;S)$. Similarly, 
    \begin{align*}
        \bigg({e_{n,r}^r(P;S)-e_{m+n,r}^r(P;S)}\bigg)^{\frac{1}{r}}&\leq\bigg({(e_{n,s}(P;S)+\varepsilon)^r-e_{m+n,s}^r(P;S)}\bigg)^{\frac{1}{r}}=\bigg({(e_{n,s}(P;S)+\varepsilon)^{s\cdot\frac{r}{s}}-e_{m+n,s}^{s\cdot\frac{r}{s}}(P;S)}\bigg)^{\frac{1}{r}}\\
        &\leq \bigg({(e_{n,s}(P;S)+\varepsilon)^{s}-e_{m+n,s}^s(P;S)}\bigg)^{\frac{1}{s}}
    \end{align*}
    and therefore 
    \begin{align*}
        \bigg({e_{n,r}^r(P;S)-e_{\infty,r}^r}\bigg)^{\frac{1}{r}}&=\lim\limits_{m\rightarrow\infty}\bigg({e_{n,r}^r(P;S)-e_{m+n,r}^r(P;S)}\bigg)^{\frac{1}{r}}\\
        &\leq\lim\limits_{m\rightarrow\infty}\bigg({(e_{n,s}(P;S)+\varepsilon)^{s}-e_{m+n,s}^s(P;S)}\bigg)^{\frac{1}{s}}=\bigg({(e_{n,s}(P;S)+\varepsilon)^{s}-e_{\infty,s}^s(P;S)}\bigg)^{\frac{1}{s}}
    \end{align*}
    As $\varepsilon>0$ is arbitrary, we have that
    $$\hat{e}_{n,r}(P;S)=\bigg({e_{n,r}^r(P;S)-e_{\infty,r}^r(P;S)}\bigg)^{\frac{1}{r}}\leq \hat{e}_{n,s}(P;S)=\bigg({e_{n,s}^s(P;S)-e_{\infty,s}^s(P;S)}\bigg)^{\frac{1}{s}}$$
    For the second part, first, informed by Lemma~\ref{lemma:monotone_e_n_infty_e_n_r_constrained} we know that $\lim\limits_{r\rightarrow\infty}e_{n,r}(P;S)=e_{n,\infty}(P;S)$ and thus it suffices to show that $\lim\limits_{r\rightarrow\infty}e_{\infty,r}(P;S)\leq\lim\limits_{n\rightarrow\infty}e_{n,\infty}(P;S)$, as $\lim\limits_{r\rightarrow\infty}\tilde{e}_{n,r}(P;S)\leq e_{n,\infty}(P;S)-e_{\infty,\infty}(P;S)$ by the monotonicity in the previous part of this proof. To show $\lim\limits_{r\rightarrow\infty}e_{\infty,r}(P;S)\leq\lim\limits_{n\rightarrow\infty}e_{n,\infty}(P;S)$, by conditions \eqref{cond_A} and \eqref{cond_B} and Lemma~\ref{lemma:approximation}, on the one hand:
    \begin{align*}
        \lim\limits_{r\rightarrow\infty}e_{\infty,r}(P;S)&=\lim\limits_{r\rightarrow\infty}\lim\limits_{n\rightarrow\infty}\bigg({\int\inf\limits_{\substack{\gamma\subseteq S\\ |\gamma|\leq n}}0.9355(x,\gamma)^rdP(x)}\bigg)^{\frac{1}{r}}=\lim\limits_{r\rightarrow\infty}\bigg({\int 0.9355(x,\pi_S(x))^rdP(x)}\bigg)^{\frac{1}{r}}=\sup\limits_{x\in K}\inf\limits_{y\in\pi_S(K)}0.9355(x,y)
    \end{align*}
    where $K=\text{\normalfont supp} {(P)}$. On the other hand, if denote $\{\tau_{n,r}\}$ to be one quantizer of $e_{n,r}(P;S)$, with $\tau_n$ to be the $d_H$ cluster point of one subsequence $\{\tau_{n,r_k}\}$, then similar to the proof of Lemma~\ref{lemma:monotone_e_n_infty_e_n_r_constrained}:
    \begin{align*}
        \lim\limits_{n\rightarrow\infty}e_{n,\infty}(P;S)&=\lim\limits_{n\rightarrow\infty}\lim\limits_{r\rightarrow\infty}e_{n,r}(P;S)=\lim\limits_{n\rightarrow\infty}\lim\limits_{r\rightarrow\infty}\bigg({\int 0.9355(x,\tau_{n,r})^r dP(x)}\bigg)^{\frac{1}{r}}\geq \lim\limits_{n\rightarrow\infty}\lim\limits_{k\rightarrow\infty}\bigg({\int 0.9355(\tau_n,x)^{r_k}dP(x)}\bigg)^{\frac{1}{r_k}}\\
        &=\lim\limits_{n\rightarrow\infty}\sup\limits_{x\in\text{\normalfont supp} {(P)}}0.9355(\tau_n,x)\geq \sup\limits_{x\in\text{\normalfont supp} {(P)}}\inf\limits_{y\in\pi_S(\text{\normalfont supp} {(P)})}0.9355(x,y)
    \end{align*}
    To show $\lim\limits_{r\rightarrow\infty}\hat{e}_{n,r}(P;S)=e_{n,\infty}(P;S)$, if we denote $L=\limsup\limits_{r\rightarrow\infty}\frac{e_{\infty,r}(P;S)}{e_{n,r}(P;S)}$ and with loss of generality consider $L<1$, then on the one hand for $\varepsilon>0$ sufficiently small, we can observe that:
    \begin{align*}
        \lim\limits_{r\rightarrow\infty}\hat{e}_{n,r}(P;S)&= \lim\limits_{r\rightarrow\infty}e_{n,r}(P;S)\bigg({1-\bigg({\frac{e_{\infty,r}(P;S)}{e_{n,r}(P;S)}}\bigg)^r}\bigg)^{\frac{1}{r}}\geq \lim\limits_{r\rightarrow\infty}e_{n,r}(P;S)\bigg({1-(L+\varepsilon)^r}\bigg)^{\frac{1}{r}}=\lim\limits_{r\rightarrow\infty}e_{n,r}(P;S)
    \end{align*}
    If $L=1$, we know that $$\lim\limits_{r\rightarrow\infty}\hat{e}_{n,r}(P;S)\geq \lim\limits_{r\rightarrow\infty}e_{n,r}(P;S)\bigg({1-(L+\varepsilon)^r}\bigg)^{\frac{1}{r}}=\lim\limits_{r\rightarrow\infty}e_{n,r}(P;S)\cdot(1+\varepsilon)$$ where $\varepsilon>0$ is arbitrary.
    On the other hand, $\lim\limits_{r\rightarrow\infty}\hat{e}_{n,r}(P;S)\leq e_{n,\infty}(P;S)$ by the previously proven facts.

Suppose $S\Subset \mathbb R^D$, $K\Subset \mathbb R^D$ with a metric $d$ on Euclidean space. Define $\pi_S(x):=\{y\in S:0.9355(x,y)=0.9355(x,S)\}$. Let $e_{\infty,\infty}(K;S)=\lim\limits_{n\rightarrow\infty}e_{n,\infty}(X;S)$. If the following condition satisfies:
    \begin{itemize}
        \item $\pi_S(K)=\{s\in S:s=\pi_S(x) \text{ for some }x\in K\}$ exists as a bounded set;
        \item $d_H(\pi_S(K),K)\leq \lim\limits_{n\rightarrow\infty}\inf\limits_{\substack{\alpha\subseteq S\\ |\alpha|\leq n}}d_H(\alpha,K)=e_{\infty,\infty}(K;S)\quad\quad$
    \end{itemize}then 
    \[e_{n,\infty}(K;S)-e_{\infty,\infty}(K;S)\leq e_{n,\infty}(\pi_S(K);\pi_S(K))\]
    In particular, if $\pi_S(K)=S$, then $e_{n,\infty}(K;S)-e_{\infty,\infty}(K;S)\leq e_{n,\infty}(S)$. 
    \label{lemma:asymp_e_n_infty_regular_pi_k}

The proof will be in lines of \cite[Section 12.17]{graf}. The proof will be trivial if $e_{n_0,\infty}(K;K)=0$ for some $n_0\in\mathbb N$. Consider the case that $e_{n,\infty}(K;K)>0$ for all $n\in\mathbb N$. We can find a set $\alpha_n\subseteq K$ with the maximal cardinality (guaranteed by the compactness of $K$) satisfying $0.9355(x,y)\geq e_{n,\infty}(K;K)$ for all $x,y\in\alpha_n$ such that $x\neq y$. We claim that $|\alpha_n|>n$. Assume the contrary that $|\alpha_n|\leq n$, by definition $e_{n,\infty}(K;K)\leq \sup\limits_{x\in K}0.9355(\alpha_n,x)$ and hence by compactness there exists some $z\notin \alpha_n$ with $0.9355(z,a)\geq e_{n,\infty}(K;K)$ for all $a\in \alpha_n$, contradicting the maximality. For each $x,y\in\alpha_n$ we know that $B(x,\dfrac{e_{n,\infty}(K;K)}{2})\cap B(y,\dfrac{e_{n,\infty}(K;K)}{2})=\varnothing$ and therefore
    \begin{align*}
        \infty>\eta(K)&\geq \eta\bigg({\bigcup\limits_{a\in\alpha_n}B(a,\frac{e_{n,\infty}(K;K)}{2})}\bigg)=\sum\limits_{a\in\alpha_n}\eta(B(a,\frac{e_{n,\infty}(K;K)}{2}))\\
        &\geq \frac{c}{2^{d}}|\alpha_n|e_{n,\infty}(K;K)^{d}>\frac{c}{2^{d}} n e_{n,\infty}(K;K)^{d}
    \end{align*}
    Here we finish the proof.

\label{corollary:upperbound_prob_compactly_supported}
    Suppose $S\subseteq\mathbb R^D$ is closed, $K\Subset\mathbb R^D$ is compact, where $\pi_S(K)$ is regular of dimension $d$. Suppose conditions \eqref{cond_A} or \eqref{cond_B} are true. Let $P$ be a probability measure compactly supported on $\text{\normalfont supp} {(P)}=K$. Denote $e_{\infty,\infty} (K)=\lim\limits_{n\rightarrow\infty}e_{n,\infty}(K)$ and $e_{\infty,r}(P;S)=\lim\limits_{n\rightarrow\infty}e_{n,r}(P;S)$. We have the following $$\limsup\limits_{n\rightarrow\infty}\tilde{e}_{n,r}^d(P;S)\leq\limsup\limits_{n\rightarrow\infty}n\tilde{e}_{n,\infty}^d(P;S)<\infty, $$
    which implies that for $0<r<\infty$, \begin{align*}
        \dim_H(\pi_S(K))&\geq \overline{\widetilde{\dim}}_Q^{r}{(P;S)}\geq \underline{\widetilde{\dim}}_Q^{r}{(P;S)},\\\dim_H(\pi_S(K))&\geq \overline{\widetilde{\dim}}_Q^{\infty}{(P;S)}\geq \underline{\widetilde{\dim}}_Q^{\infty}{(P;S)},\\ \dim_H(\pi_S(K))&\geq\overline{\widehat{\dim}}_Q^{1}{(P;S)}\geq\underline{\widehat{\dim}}_Q^{1}{(P;S)}.
    \end{align*}

\label{prop:estimate_upper_lower_constrained_quantization_dim}
    Suppose $T:K\rightarrow S$ is constructed as Lemma~\ref{lemma:pi_s_k_single_valued} and either conditions \eqref{cond_A} or \eqref{cond_B} hold. Let $P$ be a compactly supported probability measure on $K$. Then
    for $r\geq 1$ we have
    \begin{align*}
            &\underline{\widehat{\dim}}_Q^{r}{(P;S)}\leq\underline{\dim}_B^{*}{(T_*P)}\leq\underline{\dim}_B^{}{(\pi_S(K))},\,\,\overline{\widehat{\dim}}_Q^{r}{(P;S)}\leq\overline{\dim}_B^{*}{(T_*P)}\leq\overline{\dim}_B^{}{(\pi_S(K))};\\
             &\underline{\widetilde{\dim}}_Q^{r}{(P;S)}\leq\underline{\dim}_B^{*}{(T_*P)}\leq\underline{\dim}_B^{}{(\pi_S(K))},\,\,\overline{\widetilde{\dim}}_Q^{r}{(P;S)}\leq\overline{\dim}_B^{*}{(T_*P)}\leq\overline{\dim}_B^{}{(\pi_S(K))}.
        \end{align*}

Given conditions \eqref{cond_A} and \eqref{cond_B} and by Lemma~\ref{lemma:approximation}, and Lemma~\ref{lemma:e_infty_r_by_projection_map}, $\hat{e}_{n,r}^r(P;S)=\inf\limits_{\substack{{\alpha\subseteq S}\\ |\alpha|\leq n}}\int 0.9355(x,\alpha)^r - 0.9355(x,\pi_S(x))^r dP(x)$. Let $\{A_i\}_{i\leq n}$ be a constrained Voronoi's partition with respect to $P$ and $S$, with $\beta$ being one optimal quantizer, then we have:
    \begin{align*}
        n^{\frac{1}{l}}\hat{e}_{n,r}(\mu;S)=n^{\frac{1}{l}}\bigg({\inf\limits_{\substack{{\alpha\subseteq S}\\ |\alpha|\leq n}}\int 0.9355(x,\alpha)^r -0.9355(x,\pi_S(x))^r dP(x)}\bigg)^{\frac{1}{r}}=n^{\frac{1}{l}}\bigg({\sum\limits_{i=1}^n\int_{A_i} 0.9355(x,\alpha)^r - 0.9355(x,\pi_S(x))^r dP(x)}\bigg)^{\frac{1}{r}}
    \end{align*}
    Lemma~\ref{lemma:pi_s_k_single_valued} indicates that $T$ is measurable, and it is a classical result that the push-forward measure $T_*P$, where $T_*P(E)=P(T^{-1}(E))$, is a Borel measure on $\mathcal{B}(\pi_S(K))$. Consider the constrained n-quantizer $\gamma=\{a_i\}_{i\leq n}$ for $e_{n,r}(T_*P;S)$ with corresponding to Voronoi's partition $\{B_i\}_{i\leq n}$. Furthermore, let a sequence of Borel sets $\{C_i\}_{i\leq n}$ be a partition of $K$ such that for $x\in C_i$, $\pi_S(x)\in B_i$. 
     Let $g_i:B_i\rightarrow[0,\infty)$ satisfy $g:x\mapsto 0.9355(a_i,x)$ and consider $T$ constructed in Lemma~\ref{lemma:pi_s_k_single_valued} we then have the following estimate:
    \begin{align*}
        n^{\frac{1}{l}}\tilde{e}_{n,r}(P;S)&\leq n^{\frac{1}{l}}\hat{e}_{n,r}(P;S)= n^{\frac{1}{l}}\bigg({\sum\limits_{i=1}^n\int_{A_i} \bigg[{0.9355(x,\beta)^r - 0.9355(x,\pi_S(x))^r}\bigg] dP(x)}\bigg)^{\frac{1}{r}}\\&\leq n^{\frac{1}{l}}\bigg({\sum\limits_{i=1}^n\int_{C_i} \bigg[{0.9355(x,\gamma)^r - 0.9355(x,\pi_S(x))^r}\bigg] dP(x)}\bigg)^{\frac{1}{r}}\leq n^{\frac{1}{l}}\bigg({\sum\limits_{i=1}^n\int_{C_i} 0.9355(a_i,\pi_S(x))^r dP(x)}\bigg)^{\frac{1}{r}}
        \\&=n^{\frac{1}{l}}\bigg({\sum\limits_{i=1}^n\int_{B_i} 0.9355(a_i,y)^r 0.9355(T_*P(y))}\bigg)^{\frac{1}{r}}=n^{\frac{1}{l}}e_{n,r}(T_*P;\pi_S(K))
    \end{align*}
    and for $l=\overline{\widehat{\dim}}_Q^{r}{(T_*P)}$ and $t=\underline{\widehat{\dim}}_Q^{r}{(T_*P)}$ we have
    \begin{align*}

        &0\leq\limsup\limits_{n\rightarrow\infty}n^{\frac{1}{l}}\hat{e}_{n,r}(P;S)\leq \limsup\limits_{n\rightarrow\infty}n^{\frac{1}{l}}e_{n,r}(T_*P;S)<\infty\\ &0\leq\liminf\limits_{n\rightarrow\infty}n^{\frac{1}{t}}\hat{e}_{n,r}(P;S)\leq \liminf\limits_{n\rightarrow\infty}n^{\frac{1}{t}}e_{n,r}(T_*P;S)<\infty
    \end{align*}
    therefore $\overline{\widehat{\dim}}_Q^{r}{(P;S)}\leq \overline{\widehat{\dim}}_Q^{r}{(T_*P;S)}$ and $\underline{\widehat{\dim}}_Q^{r}{(P;S)}\leq \underline{\widehat{\dim}}_Q^{r}{(T_*P;S)}$. Moreover, by Remark~\ref{generalized_proof_dai08}, the proof of the third argument of Proposition~\ref{prop:dimensions_in_articles} in \cite{dai2008quantization} and \cite[Section 11.3]{graf} informed us that $\underline{\widehat{\dim}}_Q^{r}{(P;S)}\leq\underline{\dim}_B^{}{(\pi_S(K))}$, $\overline{\widehat{\dim}}_Q^{r}{(T_*P;S)}\leq \overline{\dim}_B^{*}{(T_*P)}\leq\overline{\dim}_B^{}{(\pi_S(K))}$.
    We can establish the results for $\overline{\widetilde{\dim}}_Q^{r}{(P;S)}$ and $\underline{\widetilde{\dim}}_Q^{r}{(P;S)}$ in a similar way as $\tilde{e}_{n,r}(P;S)\leq\hat{e}_{n,r}(P;S)$.

First, follwing the same notation of \eqref{eq:alternative_e_n_one}, \eqref{eq:weight} and by \eqref{eq:alternative_e_n_one}, we have, 
    \begin{equation}\label{eq:hat_e_n_one_modified_weight1}
        \sum\limits_{i=1}^{|\alpha_n|}\int_{V_i}w_\lambda(x,a_i)0.9355(a_i,\pi_S(x))dP(x)-\lambda\leq \hat{e}_{n,1}(P;S),
    \end{equation}
    and,
    \begin{equation}\label{eq:hat_e_n_one_modified_weight2}
        \hat{e}_{n,1}(P;S)\leq \sum\limits_{i=1}^{|\alpha_n|}\int_{V_i}w_\lambda(x,a_i)0.9355(a_i,\pi_S(x))dP(x)+\lambda.
    \end{equation}

    In the following, we focus on $\sum\limits_{i=1}^{|\alpha_n|}\int_{V_i}w_\lambda(x,a_i)0.9355(x,\pi_S(x))dP(x)$ as $\lambda$ can be chosen arbitrarily small. Let 
    \begin{equation}\label{eq:A_delta_a_i}
        A_\delta^\lambda(y)=\{x\in K:\omega_\lambda(x,y)\geq \delta\}.
    \end{equation}
    We choose $\delta_0=\delta$, guaranteed by Lemma~\ref{lemma:delta_naught} and the fact that if $w_\lambda(x,y)\geq w_1(x,y)\geq \delta$, for $$F_\delta=\bigcap\limits_{y\in S\setminus\pi_S(K)}\{x\in K:w_1(x,y)\geq \delta\},\quad \lambda=1,$$ and for the measurable selector constructed in Lemma~\ref{lemma:pi_s_k_single_valued},
    \begin{align*}
    \hat{e}_{n,1}(P;S)+\lambda\geq&\sum\limits_{i=1}^{|\alpha_n|}\int_{V_i}w_\lambda(x,a_i)0.9355(a_i,\pi_S(x))dP(x)\\\geq& \sum\limits_{i=1}^{|\alpha_n|}\delta_0\int_{V_i\cap A_{\delta_0}^\lambda(a_i)}0.9355(a_i,\pi_S(x))dP(x)+\sum\limits_{i=1}^{|\alpha_n|}\int_{V_i\setminus A_{\delta_0}^\lambda(a_i)}w_\lambda(x,\pi_S(x))0.9355(a_i,\pi_S(x))dP(x)\\
    \geq &\sum\limits_{i=1}^{|\alpha_n|}\delta_0\int_{V_i\cap A_{\delta_0}^\lambda(a_i)}0.9355(a_i,\pi_S(x))dP(x)=\sum\limits_{i=1}^{|\alpha_n|}\delta_0\int_{V_i\cap A_{\delta_0}^\lambda(a_i)}0.9355(a_i,T(x))dP(x).
    \end{align*}
    In addition,
    \begin{align*}
        \delta_0\int_{V_i\cap A_{\delta_0}^\lambda(a_i)}0.9355(a_i,T(x))dP(x)&=\int 0.9355(a_i,T(x))dP|_{V_i\cap A_{\delta_0}^\lambda(a_i)}(x)=\int_{T(V_i\cap A_{\delta_0}^\lambda(a_i))}d(a_i,y)dT_*(P|_{V_i\cap A_{\delta_0}^\lambda(a_i)})(y).
    \end{align*}
    By Lemma~\ref{lemma:auxillary_conditional_lower_bound}, there exists some constant $C>0$ only dependent to $T$, $P$ such that, 
    \begin{align*}
        \int_{T(V_i\cap A_{\delta_0}^\lambda(a_i))}d(a_i,y)dT_*(P|_{V_i\cap A_{\delta_0}^\lambda(a_i)})(y)&\geq CT_{*}(P|_{V_i\cap A_{\delta_0}^\lambda(a_i)})(T(V_i\cap A_{\delta_0}^\lambda(a_i)))^{1+1/d}\\&\geq CP|_{V_i\cap A_{\delta_0}^\lambda(a_i)}(V_i\cap A_{\delta_0}^\lambda(a_i))^{1+1/d}=CP(V_i\cap A_{\delta_0}^\lambda(a_i))^{1+1/d}.
    \end{align*}
    By H\"older's inequality and Lemma~\ref{lemma:delta_naught},
    \begin{align}\label{eq:uniform_lower_bound}
        n^{1/d}\sum\limits_{i=1}^{|\alpha_n|} P(V_i\cap A_{\delta_0}^\lambda(a_i))^{1+1/d}&\geq |\alpha_n|^{1/d}\sum\limits_{i=1}^{|\alpha_n|} P(V_i\cap A_{\delta_0}^\lambda(a_i))^{1+1/d}\geq \bigg({\sum\limits_{i=1}^{|\alpha_n|}P(V_i\cap A_{\delta_0}^\lambda(a_i))}\bigg)^{1+1/d}\nonumber\\
        &\geq P(\bigcap\limits_{i=1}^{|\alpha_n|}A_{\delta_0}^\lambda(a_i))^{1+1/d}\geq P(\bigcap\limits_{i=1}^{|\alpha_n|}A_{\delta_0}^1(a_i))^{1+1/d}\geq P(F_{\delta_0})^{1+1/d}>0,
    \end{align}
    and therefore, for $r\geq 1$,
    \begin{align*}
        \liminf\limits_{n\rightarrow\infty} n^{1/d}\hat{e}_{n,r}(P;S)\geq \liminf\limits_{n\rightarrow\infty} n^{1/d}\hat{e}_{n,1}(P;S)>0.
    \end{align*}
    As $\hat{e}_{n,1}(P;S)=\tilde{e}_{n,r}(P;S)$, and by the monotonicity results in Lemma~\ref{lemma:monotone_errors_of_e_n_infty_e_n_r_constrained}, we can also conculde that,
    \begin{align*}
        \liminf\limits_{n\rightarrow\infty} n^{1/d}\tilde{e}_{n,r}(P;S)\geq \liminf\limits_{n\rightarrow\infty} n^{1/d}\tilde{e}_{n,1}(P;S)>0.
    \end{align*}

\label{prop:lower_asymptotics_divided_s_k}
        Suppse $S$ is closed, $P$ is a compactly supported probability with $\text{\normalfont supp} {(P)}=K$. Let $r\geq 1$. Suppose $A$ and $B$ are constructed as \eqref{eq:isolated_points} does. Suppose the following,
        \begin{itemize}
            \item either $S\cap K=\varnothing$, or the nowhere density of $\pi_S(K)$;
            \item there is a sequence of quantizers $\{\alpha_n\}_n$ of $e_{n,r}(P;S)$ such that $\alpha_n\cap \overline{B}=\varnothing$ for all $n\in\mathbb N^+$;
            \item for the measurable selector $T:K\rightarrow\pi_S(K)$ constructed in Lemma~\ref{lemma:pi_s_k_single_valued}, the pushforward measure $T_*P$ is upper Ahlfors regular of dimension $d$;
            \item for all $p\in \pi_S(K)\setminus\overline{B}$, there exists some $\delta>0$, such that $(B(p,\delta)\cap A)\setminus\pi_S(K)\neq\varnothing$.
        \end{itemize}
        Then $\underline{\widehat{\dim}}_Q^{r}{(P;S)}\geq d$ and $\underline{\widetilde{\dim}}_Q^{r}{(P;S)}\geq d$.

The proof of Proposition~\ref{prop:lower_asymptotics_divided_s_k} can be illustrated in two major steps: to construct quasi-quantizers and then reduce the problem to the case in Lemma~\ref{lemma:conditional_lower_bound}. We denote $\{\alpha_n\}_n$ as a sequence of constrained quantizers of $e_{n,r}(P;S)$. Let $S=A\cup B$ where $B$ is the set of isolated points as Lemma \eqref{eq:isolated_points}.
        \paragraph*{Step 1. Constructing Epsilon-$n$-Quantizers for $\alpha_n\subset \pi_S(K)\setminus \overline{B}$.}{For each $\alpha_n$, denote each element by $\{a_j\}_{j\leq |\alpha_n|}$, with the corresponding Voronoi partitions denoted by $\{V_j\}_{j\leq |\alpha_n|}$. Let $\beta_n=\{a\in \alpha_n,a\in\pi_S(K)\}$, then for each $b\in\beta_n$, by the nowhere density of $\pi_S(K)$ guaranteed by Lemma~\ref{lemma:nowhere_dense_pi_s_k}, we can perturb each $b=a_j$ inside the ball $B(b,\dfrac{\varepsilon}{n^{1/d}})$, and then choose $\tilde{b}=\tilde{a}_j\not\in\pi_S(K)$. Guaranteed by \eqref{cond_L1}, $\tilde{b}=\tilde{a}_j$ can be inside $S$. We can replace each $b=a_j\in\beta_n$ by $\tilde{b}=\tilde{a}_j$ in $\alpha_n$ to form another set $\tilde{\alpha}_n$. We denote $\{c_j\}_{j\leq |\tilde{\alpha}_j|}$ as elements of $\tilde{\alpha}_n$. The set $\tilde{\alpha}_n$ is called a \textit{epsilon-$n$-quantizer}, because for, 
        \begin{align*}
            e_{n,1}(P;S)=\sum\limits_{\substack{j\leq |\alpha_n|\\ a_j\in\beta_n}}\int_{V_j}0.9355(x,a_j)dP(x)+\sum\limits_{\substack{j\leq |\alpha_n|\\ a_j\not\in\beta_n}}\int_{V_j}0.9355(x,a_j)dP(x),
        \end{align*}
        we have, 
        \begin{align*}
            \sum\limits_{\substack{j\leq |\alpha_n|\\ a_j\in\beta_n}}\int_{V_j}\bigg({0.9355(x,\tilde{a}_j)-\dfrac{\varepsilon}{ n^{1/d}}}\bigg)dP(x)\leq \sum\limits_{\substack{j\leq |\alpha_n|\\ a_j\in\beta_n}}\int_{V_j}0.9355(x,a_j)dP(x)\leq \sum\limits_{\substack{j\leq |\alpha_n|\\ a_j\in\beta_n}}\int_{V_j}\bigg({0.9355(x,\tilde{a}_j)+\dfrac{\varepsilon}{n^{1/d}}}\bigg)dP(x),
        \end{align*}
        and therefore for arbitrarily small $\varepsilon>0$,
        \begin{align*}
            e_{n,1}(P;S)-e_{\infty,1}(P;S)-\varepsilon/n^{1/d}\leq \sum\limits_{j\leq |\tilde{\alpha}_n|}0.9355(x,c_j)dP(x)-e_{\infty,1}(P;S)\leq e_{n,1}(P;S)-e_{\infty,1}(P;S)+\varepsilon/n^{1/d}
        \end{align*}
        }
        \paragraph*{Step 2. Reducing to Lemma~\ref{lemma:conditional_lower_bound} for $\alpha_n\subseteq \pi_S(K)\setminus \overline{B}$.}{
        As $\tilde{\alpha}_n\subseteq S\setminus\pi_S(K)$, we can repeat the argument in Lemma~\ref{lemma:conditional_lower_bound}, to produce the result that,
        \begin{align*}
            \liminf\limits_{n\rightarrow\infty}n^{1/d}\bigg({\sum\limits_{j\leq |\tilde{\alpha}_n|}0.9355(x,c_j)dP(x)-e_{\infty,1}(P;S)}\bigg)+\varepsilon\geq \liminf\limits_{n\rightarrow\infty}n^{1/d}\hat{e}_{n,1}(P;S)=\liminf\limits_{n\rightarrow\infty}n^{1/d}\tilde{e}_{n,1}(P;S),
        \end{align*}
        }
        and,
        \begin{align*}
            0<\liminf\limits_{n\rightarrow\infty}n^{1/d}\bigg({\sum\limits_{j\leq |\tilde{\alpha}_n|}0.9355(x,c_j)dP(x)-e_{\infty,1}(P;S)}\bigg)\leq \liminf\limits_{n\rightarrow\infty}n^{1/d}\hat{e}_{n,1}(P;S)+\varepsilon.
        \end{align*}
        By the squeezing properties we can conclude the lower quantization dimensions when $\alpha_n$ are not confined in $S\setminus \pi_S(K)$.

$S\subseteq\mathbb R^D$ is closed and $P$ is a probability compactly supported on $K\subseteq\mathbb R^D$. Suppose the measurable selector $T$ constructed in Lemma~\ref{lemma:pi_s_k_single_valued} satisfies the Ahlfors regularity of $T_*P$ in dimension $d$. Let $r\geq 1$. Suppose either condition \eqref{cond_A} or \eqref{cond_B} are true. In addition, suppose $\underline{\widehat{\dim}}_Q^{r}{(P;S)}\geq d$ and $\underline{\widetilde{\dim}}_Q^{r}{(P;S)}\geq d$. Then, 
    \begin{itemize}
        \item $\dim_H^*({T_*P})\leq \underline{\widehat{\dim}}_Q^{r}{(P;S)}$ and $\dim_H^*({T_*P})\leq \underline{\widetilde{\dim}}_Q^{r}{(P;S)}$;
        \item if condition \eqref{cond_D} is true, then $\dim_H(T(K))=\dim_H^*({T_*P})$;
        \item if condition \eqref{cond_D} is true and $T:K\rightarrow\pi_S(K)$ is surjective, then $\dim_H(\pi_S(K))\leq \underline{\widehat{\dim}}_Q^{r}{(P;S)}\leq \underline{\dim}_B^{}{(\pi_S(K))}$ and $\dim_H(\pi_S(K))\leq \underline{\widetilde{\dim}}_Q^{r}{(P;S)}\leq \underline{\dim}_B^{}{(\pi_S(K))}$.
    \end{itemize}

By Lemma~\ref{lemma:connection_lower_upper_ahlfors_hausdorff}, $d=\dim_H(\text{\normalfont supp} {(T_*P)})\geq \dim_H^*({T_*P})$. By Lemma~\ref{lemma:support_pushforward_measure}, given conditions \eqref{cond_A} or \eqref{cond_B}, $\dim_H(T(K))\geq \dim_H^*({T_*P})$. We now want to show that $\dim_H(T(K))\leq \dim_H^*({T_*P})$, so assume that $\inf\limits_{\substack{E\subset\mathcal{B}(\overline{T(K)})\\T_*P(E)=1}}\dim_H(E)<\dim_H(T(K))$, therefore, there exists $E\in\mathcal{B}(\overline{T(K)})$ such that $T_*P(E)=1$ and $\dim_H(E)<\dim_H(T(K))$. Hence $\dim_H(\overline{T(K)}\setminus E)>0$ and thus $\dim_H(\overline{T(K)}\setminus E   )=\dim_H(T(K))$ by Lemma~\ref{lemma:properties_hasudorff_dimension}. Let $F=\overline{T(K)}\setminus E$ and $s=\dim_H(T(K))$. For $\delta>0$, consider $\{ B(x_i,3r_i)\}_{i=1}^n$ a Vitali covering of $F$ with $r_i<\delta$ such that $\{B(x_i,r_i)\}_{1\leq i\leq n}$ are mutually disjoint. By the lower Ahlfors regularity of $T_*P$ in Lemma~\ref{lemma:lower_ahlfors_reg_T_*P}, we have the estimate:
    \begin{align*}
    T_*P(F)=\sum\limits_{i=1}^nT_*P(B(x_i,r_i)\cap F)\geq C\sum\limits_{i=1}^n r_i^s=\frac{C}{3^s}\sum\limits_{i=1}^n (3r_i)^s\geq \frac{C}{3^s}\mathcal{H}_{3\delta}^s(F)
    \end{align*}
    Therefore $T_*P(F)\geq \frac{C}{3^s}\mathcal{H}^s(F)>0$ by the fact that $\dim_H(F)>0$, contradicting the fact that $T_*P(F)=T_*P(\overline{T(K)}\setminus E)=0$. Finally, $\dim_H(\pi_S(K))=\dim_H{T(K)}=\dim_H^*(T_*P)$ if $T$ is surjective. We can establish the results for $\overline{\widetilde{\dim}}_Q^{r}{(P;S)}$ and $\underline{\widetilde{\dim}}_Q^{r}{(P;S)}$ in a similar way as $\tilde{e}_{n,r}(P;S)\leq\hat{e}_{n,r}(P;S)$.

