    S(K)=S$. $\dim_H(T(K))=\dim_H(K)=0$. We may verify that $\pi_S^{-1}(B(x,\varepsilon)\cap S)=\{y\in \{(0,0)\}:\pi_S(y)\in B(x,\varepsilon)\cap S\}=\varnothing$ as $\pi_S^{-1}(\{(0,0)\})=S$, and therefore the condition \eqref{cond_A} does not hold. The condition \eqref{cond_B} does not hold either as, for a randomly selected $\beta_n\subset S\text{ with }|\beta_n|=1$ are a sequence of quantizers, which does not satisfy that $\lim\limits_{n\rightarrow\infty}d_H(\beta_n, \pi_S(K))=0$.

\label{lemma:properties_hasudorff_dimension}
    For $\{A_i\}_{i\geq1}$ a sequence of sets in $\mathbb R^D$, and $A\subseteq B\subseteq\mathbb R^D$:
    \begin{itemize}
        \item $\dim_H(\bigcup\limits_{i=1}^\infty A_i)=\sup\limits_{1\leq i<\infty}\dim_H(A_i)$;
        \item If $\dim_H(A)>0$, then $\text{\normalfont diam}(A)>0$;
        \item If $\dim_H(A)<\dim_H(B)$, then $\dim_H(A\setminus B)>0$
    \end{itemize}

\label{lemma:connection_lower_upper_ahlfors_hausdorff}
    Let $X$ be a seperable metric space. Suppose for $E\subset X$ is a closed set in $X$ upon which there exists a positive measure $\eta:\mathcal{B}(E)\rightarrow[0,\infty]$, then
    \begin{itemize}
        \item Suppose $\eta$ is lower Ahlfors regular of dimension $s$, that is, there exists $c,r_0>0$, for any $x\in E$ and $r<r_0$ we have $\eta(B(x,r)\cap S)\geq cr^s$. Then $s\geq\dim_H(E)$
        \item Suppose $\eta$ is upper Ahlfors regular of dimension $s$, that is, there exists $c,r_0>0$, for any $x\in E$ and $r<r_0$ we have $\eta(B(x,r)\cap S)\leq cr^s$. Then $s\leq \dim_H(E)$.
    \end{itemize}

For the first argument, by the general Vitali covering lemma, there exists a sequence of balls $\{B(x_i,r_i)\}_{i=1}^\infty$ with $r_i<r_0$ such that $\{B(x_i,5r_i)\}_{i=1}^\infty$ cover $E$ while $B(x_i,x_j)$ are mutually disjoint.
    Therefore
    \begin{align*}
        \eta(E)\geq \sum\limits_{i=1}^\infty \eta(B(x_i,r_i)\cap E)\geq c\sum\limits_{i=1}^\infty r_i^s
    \end{align*}
    and
    \begin{align*}
        \mathcal{H}_\delta^s(E)=\inf\limits_{\substack{E\subseteq \bigcup\limits_{i=1}^\infty U_i\\ \text{\normalfont diam}(U_i)<\delta}}\sum\limits_{i=1}^\infty \text{\normalfont diam}(U_i)^s\leq 5^s\inf\limits_{\substack{E\subseteq \bigcup\limits_{i=1}^\infty B(x_i,5r_i)\\5r_i<r}}\sum\limits_{i=1}^\infty r_i^s\leq 5^sc\eta(E)
    \end{align*}
    thus $\mathcal{H}^s(E)\leq 5^sc\eta(E)$ which implies that $s\geq \dim_H(E)$. For the second argument, for sufficiently small $\delta>0$, we have
    \begin{align*}
        \mathcal{H}_\delta^s(E)=\inf\limits_{\substack{E\subseteq \bigcup\limits_{i=1}^\infty U_i\\ \text{\normalfont diam}(U_i)<\delta}}\sum\limits_{i=1}^\infty \text{\normalfont diam}(U_i)^s\geq c\sum\limits_{i=1}^\infty\eta(B(x_i,\text{\normalfont diam}(U_i))\cap S)\geq c\sum\limits_{i=1}^\infty \eta(U_i\cap S)\geq c\eta(E)
    \end{align*}
    where $x_i$ are arbitrarily selected from $U_i$. This implies that $s\leq \dim_H(E)$.
